package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.parser.TagType;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen2Test {

    private Element element;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "http://example.com", new Attributes());
        element.attr("id", "testId");
        element.appendText("Sample text");
    }

    @Test
    public void testCloneNotNull() {
        Element clone = element.clone();
        assertNotNull(clone);
    }

    @Test
    public void testCloneDifferentObject() {
        Element clone = element.clone();
        assertNotSame(element, clone);
    }

    @Test
    public void testCloneTagName() {
        Element clone = element.clone();
        assertEquals("div", clone.tagName());
    }

    @Test
    public void testCloneId() {
        Element clone = element.clone();
        assertEquals("testId", clone.id());
    }

    @Test
    public void testCloneTextContent() {
        Element clone = element.clone();
        assertEquals("Sample text", clone.text());
    }

    @Test(expected = CloneNotSupportedException.class)
    public void testCloneShouldNotSupportCloneNotSupportedException() {
        Element clone = element.clone();
        // This should not throw CloneNotSupportedException
    }

    @Test
    public void testCloneWithNestedElements() {
        Element parent = new Element(Tag.valueOf("div"), "http://example.com", new Attributes());
        Element child = new Element(Tag.valueOf("span"), "http://example.com", new Attributes());
        child.appendText("Nested text");
        parent.appendChild(child);

        Element clone = parent.clone();
        assertEquals("div", clone.tagName());
        assertEquals("span", clone.child(0).tagName());
        assertEquals("Nested text", clone.child(0).text());
    }

    @Test
    public void testCloneWithAttributes() {
        element.attr("class", "testClass");
        Element clone = element.clone();
        assertEquals("testClass", clone.attr("class"));
    }

    @Test
    public void testCloneEmptyElement() {
        Element emptyElement = new Element(Tag.valueOf("br"), "http://example.com", new Attributes());
        Element clone = emptyElement.clone();
        assertEquals("br", clone.tagName());
        assertEquals(0, clone.children().size());
    }

    @Test
    public void testCloneWithDataAttributes() {
        element.attr("data-test", "value");
        Element clone = element.clone();
        assertEquals("value", clone.attr("data-test"));
    }
}
